set -e
cd "$(dirname "$0")"
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory site --cert server.pem --key server.key https://127.0.0.1:8080/ &
surl --proxy http://127.0.0.1:8081/ --proxy https://127.0.0.1:8082/ --cert server.pem --key server.key -v --log-file proxy.log &
sleep 1
curl -s --cacert server.pem -x http://127.0.0.1:8081/ https://127.0.0.1:8080/hello.txt
